<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { onBeforeRouteLeave, useRoute } from 'vue-router'
import { readFeature, writeFeature, featureError, type Attempt, type Feedback, type Page } from '@/services/additionalFeatures'
import { gatewayUrl } from '@/api/authApi'
import { plain } from '@/services/operationsApi'
import '@/components/operations/operations.css'
const route=useRoute(),id=Number(route.params.id),attempt=ref<Attempt>(),answers=ref<Record<number,string>>({}),notes=ref<Feedback[]>([]),error=ref(''),message=ref(''),saving=ref(false),submitting=ref(false),now=ref(Date.now())
let offset=0,dirty=false,stopped=false,autoRetryAt=0,timer:ReturnType<typeof setInterval>|undefined,debounce:ReturnType<typeof setTimeout>|undefined,pending:Promise<void>|undefined
const remaining=computed(()=>Math.max(0,Math.ceil(((attempt.value?.endsAt||now.value)-now.value)/1000)))
const clock=computed(()=>`${Math.floor(remaining.value/60)}:${String(remaining.value%60).padStart(2,'0')}`)
function accept(data:Attempt){attempt.value=data;offset=data.serverNow-Date.now();now.value=Date.now()+offset}
async function load(){try{const data=await readFeature<Attempt>(`/api/nihongo-user/study/attempts/${id}`);if(stopped)return;accept(data);answers.value=Object.fromEntries(data.questions.filter(q=>q.chosen).map(q=>[q.id,q.chosen!]))}catch(cause){error.value=featureError(cause)}}
async function flush(){if(pending){await pending;if(dirty&&!attempt.value?.finished)await flush();return}if(!dirty||!attempt.value||attempt.value.finished||stopped)return;clearTimeout(debounce);const payload={answers:{...answers.value},version:attempt.value.version};dirty=false;saving.value=true;pending=gatewayUrl.put<Attempt>(`/api/nihongo-user/study/attempts/${id}/answers`,payload).then(response=>{if(!stopped){accept(response.data);message.value=response.data.finished?'Đã hết giờ, bài được chấm theo đáp án đã lưu.':'Đã lưu đáp án.'}}).catch(cause=>{dirty=true;error.value=featureError(cause);throw cause}).finally(()=>{pending=undefined;saving.value=false});await pending;if(dirty&&!stopped&&!attempt.value?.finished)await flush()}
function choose(){dirty=true;message.value='Chưa lưu';clearTimeout(debounce);debounce=setTimeout(()=>{void flush().catch(()=>{})},700)}
async function submit(automatic=false){if(submitting.value||!attempt.value||attempt.value.finished||automatic&&Date.now()<autoRetryAt)return;if(!automatic&&!confirm('Nộp bài? Sau khi nộp bạn không thể sửa đáp án.'))return;submitting.value=true;error.value='';try{await flush();if(attempt.value.finished)return;const data=await writeFeature<Attempt>(`/api/nihongo-user/study/attempts/${id}/submit`,{answers:answers.value,version:attempt.value.version});if(!stopped)accept(data)}catch(cause){error.value=featureError(cause)}finally{submitting.value=false;if(automatic)autoRetryAt=Date.now()+10000}}
async function feedback(){try{notes.value=(await readFeature<Page<Feedback>>(`/api/nihongo-user/study/attempts/${id}/feedback`)).content}catch(cause){error.value=featureError(cause)}}
const leaving=(event:BeforeUnloadEvent)=>{if(dirty||saving.value){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(async()=>{if(dirty||pending){try{await flush()}catch{return confirm('Một số đáp án chưa lưu. Vẫn rời bài làm?')}}return true})
onMounted(async()=>{timer=setInterval(()=>{now.value=Date.now()+offset;if(attempt.value&&!attempt.value.finished&&remaining.value===0)void submit(true)},1000);window.addEventListener('beforeunload',leaving);await load();if(!stopped)await feedback()})
onUnmounted(()=>{stopped=true;clearInterval(timer);clearTimeout(debounce);window.removeEventListener('beforeunload',leaving)})
</script>
<template><div class="ops-page"><RouterLink to="/user/assignments">← Bài được giao</RouterLink><header class="ops-heading"><h1>{{ attempt?.title || 'Bài làm' }}</h1><strong v-if="attempt && !attempt.finished" role="timer">Còn {{ clock }}</strong></header><p v-if="error" class="ops-error" role="alert">{{ error }} <button class="ops-button secondary" @click="flush().catch(()=>{})">Thử lưu lại</button></p><p v-if="message" class="ops-muted" role="status">{{ message }}</p><section v-if="attempt?.finished" class="ops-panel"><h2>Kết quả: {{ attempt.score }} / 100</h2><p>Đúng {{ attempt.correct }} / {{ attempt.total }} câu. {{ attempt.answersVisible ? 'Đáp án đã được mở.' : 'Đáp án sẽ mở sau hạn làm đề.' }}</p></section><section v-for="(question,index) in attempt?.questions || []" :key="question.id" class="ops-panel"><h2>Câu {{ index+1 }}</h2><p class="ops-content">{{ plain(question.content) }}</p><div class="ops-grid"><label v-for="option in ['A','B','C','D'] as const" :key="option" class="ops-panel"><input v-model="answers[question.id]" type="radio" :name="`question-${question.id}`" :value="option" :disabled="attempt?.finished || submitting || remaining===0" @change="choose"> {{ option }}. {{ plain(question[`answer${option}`]) }}</label></div><p v-if="question.correctAnswer" class="ops-success">Đáp án: {{ question.correctAnswer }} · Bạn chọn: {{ question.chosen || 'Chưa chọn' }}</p></section><div v-if="attempt && !attempt.finished" class="ops-actions"><button class="ops-button secondary" :disabled="saving||submitting" @click="flush().catch(()=>{})">Lưu đáp án</button><button class="ops-button" :disabled="submitting" @click="submit()">{{ submitting?'Đang nộp...':'Nộp bài' }}</button></div><section class="ops-panel"><h2>Nhận xét của giảng viên</h2><button class="ops-button secondary" @click="feedback">Tải nhận xét</button><p v-if="!notes.length" class="ops-muted">Chưa có nhận xét.</p><article v-for="note in notes" :key="note.id"><strong>{{ note.questionId ? `Câu có mã ${note.questionId}` : 'Nhận xét chung' }}</strong><p class="ops-content">{{ note.text }}</p></article></section></div></template>
